-- 449_hidden_curated.sql — #449 Las Vegas story batch: 14 HIDDEN storyless OSM pins brought back with a story (drafted 2026-11-02).
-- Same shape and rules as 448_hidden_curated.sql: exact stored name at the stored coordinate, read from the stored places:v34 rows.
-- Every pin is hidden in the live serve (449_leads_las_vegas.tsv / the gate dry run's drops) and passed #542 by pin id — its
-- containing tile stores it. These are the gate rescues (step 3, FROM PITTSBURGH (7)): HMdb markers within 1-18 m of the pin
-- (the Rat Pack plaque; the Wengert Mansion, which houses the Haunted Museum; the Bow & Arrow, Jerry's Nugget and Silver Slipper
-- signs and the Neon Boneyard Park sign, from the Neon Museum's plaques — excluded from the depth bar as a series, used here
-- because each labels this exact sign), and Wikipedia articles that tell the pin's own story (MGM Grand's lion, New York-New
-- York's Statue of Liberty, Bliss Dance, the Flashlight, the Tarkanian statue, the Barrick Museum, the Sahara West Library, the
-- Hacienda horse-and-rider sign). Batch file — run in the Mac session after the seed commit, then curated_category_backfill(true);
-- every row should report dist_m 0.
with v(name, lat, lng, description, source_url, note) as (values
  ($t$The Rat Pack Memorial Plaque$t$, 36.1218284::double precision, -115.1712898::double precision, $t$The famous photo of the Rat Pack, Frank Sinatra, Dean Martin, Sammy Davis Jr., Peter Lawford and Joey Bishop, was taken on this spot beside the Strip in 1960, when the five headlined the Copa Room at the Sands; footprints mark where they stood.$t$, $t$https://www.hmdb.org/m.asp?m=247292$t$, $t$#449 hidden-pin row: osm_node12400346737, stored in 722_-2303, 722_-2304; containing tile 722_-2303 stores it (#542)$t$),
  ($t$Zak Bagan's The Haunted Museum$t$, 36.1583815::double precision, -115.1456381::double precision, $t$The museum fills the Wengert Mansion, a 1938 Tudor Revival home by architect H. Clifford Nordstrom and among the largest in Las Vegas, built for Cyril and Lottie Wengert; he was an incorporator of the utility now called NV Energy.$t$, $t$https://www.hmdb.org/m.asp?m=271054$t$, $t$#449 hidden-pin row: osm_way806953202, stored in 723_-2302, 723_-2303; containing tile 723_-2303 stores it (#542)$t$),
  ($t$Bow & Arrow Motel Neon Sign$t$, 36.1763605::double precision, -115.1361501::double precision, $t$This sign first stood at the Bow and Arrow Motel on Wyoming Avenue downtown; the Allied Arts Council gave it to the Neon Museum in 2001, and it went up here on Las Vegas Boulevard in 2009 as part of the Neon Signs Project.$t$, $t$https://www.hmdb.org/m.asp?m=145470$t$, $t$#449 hidden-pin row: osm_node5250961039, stored in 723_-2303, 724_-2302, 724_-2303; containing tile 724_-2303 stores it (#542)$t$),
  ($t$Jerry Sign$t$, 36.1767359::double precision, -115.135087::double precision, $t$This Jerry's Nugget cabinet once rotated atop a tower of letters spelling "Nugget" at the North Las Vegas locals' casino; made around the 1970s with skeleton neon and hand lettering, it was restored with a gift from founder Angelo Stamis for the casino's 50th anniversary.$t$, $t$https://www.hmdb.org/m.asp?m=92471$t$, $t$#449 hidden-pin row: osm_node5251003425, stored in 724_-2302, 724_-2303; containing tile 724_-2303 stores it (#542)$t$),
  ($t$Silver Slipper Neon Sign$t$, 36.1771151::double precision, -115.1357017::double precision, $t$Designed by Jack Larsen and built by the Young Electric Sign Company, the Silver Slipper first stood on the grounds of the Last Frontier on Las Vegas Boulevard; restored, it went up in this median in 2009 with the Bow and Arrow Motel sign and Binion's Horseshoe.$t$, $t$https://www.hmdb.org/m.asp?m=92469$t$, $t$#449 hidden-pin row: osm_node5250961036, stored in 723_-2303, 724_-2302, 724_-2303; containing tile 724_-2303 stores it (#542)$t$),
  ($t$Neon Museum Sign$t$, 36.1774573::double precision, -115.1352221::double precision, $t$Each letter of "Neon" on this Boneyard Park sign borrows a famous sign's lettering: the first N from the Golden Nugget, the e from Caesars Palace, the o from Binion's Horseshoe and the last n from the Desert Inn, all signs now kept in the Neon Museum Boneyard.$t$, $t$https://www.hmdb.org/m.asp?m=71210$t$, $t$#449 hidden-pin row: osm_node5251003419, stored in 724_-2302, 724_-2303; containing tile 724_-2303 stores it (#542)$t$),
  ($t$Hacienda Horse Neon Sign$t$, 36.1691214::double precision, -115.1407477::double precision, $t$This YESCO sign of a cowboy riding a palomino horse stood at the Hacienda resort on the Strip; the Neon Museum had it refurbished for $60,000, and installed here at Fremont Street it became the first sign of the Neon Signs Project.$t$, $t$https://en.wikipedia.org/wiki/Hacienda_(Las_Vegas)$t$, $t$#449 hidden-pin row: osm_node5250961022, stored in 723_-2303, 724_-2303; containing tile 723_-2303 stores it (#542)$t$),
  ($t$Leo the Lion$t$, 36.1012755::double precision, -115.1724052::double precision, $t$MGM Grand's 45-foot bronze lion, designed by Snellen Johnson and set on a 25-foot pedestal, is the largest bronze statue in the U.S.; it replaced the resort's original lion-head entrance, removed in 1997 partly because Asian gamblers saw walking through a lion's mouth as bad luck.$t$, $t$https://en.wikipedia.org/wiki/MGM_Grand_Las_Vegas$t$, $t$#449 hidden-pin row: osm_way1115332185, stored in 722_-2303, 722_-2304; containing tile 722_-2303 stores it (#542)$t$),
  ($t$Statue of Liberty$t$, 36.1012976::double precision, -115.1735546::double precision, $t$After the September 11 attacks a spontaneous memorial of thousands of items grew in front of this replica, and an official memorial stood here from 2003 to 2013; it is also the statue on the Postal Service's 2010 Statue of Liberty Forever stamp, picked by mistake from a stock photo.$t$, $t$https://en.wikipedia.org/wiki/New_York-New_York_Hotel_and_Casino$t$, $t$#449 hidden-pin row: osm_way115663314, stored in 722_-2303, 722_-2304; containing tile 722_-2303 stores it (#542)$t$),
  ($t$Bliss Dance$t$, 36.1034293::double precision, -115.1759371::double precision, $t$Marco Cochrane's 40-foot steel dancer was introduced at Burning Man, stood on San Francisco's Treasure Island until 2015 and then moved permanently to The Park, which opened near T-Mobile Arena in 2016; it weighs more than 7,500 pounds.$t$, $t$https://en.wikipedia.org/wiki/Marco_Cochrane$t$, $t$#449 hidden-pin row: osm_node5508838247, stored in 722_-2303, 722_-2304; containing tile 722_-2304 stores it (#542)$t$),
  ($t$The Flashlight$t$, 36.1101102::double precision, -115.1392781::double precision, $t$Claes Oldenburg's Flashlight sculpture was installed in 1981 on this UNLV plaza between Artemus Ham Hall and Judy Bayley Theatre.$t$, $t$https://en.wikipedia.org/wiki/University_of_Nevada,_Las_Vegas$t$, $t$#449 hidden-pin row: osm_way1382413813, stored in 722_-2302, 722_-2303; containing tile 722_-2303 stores it (#542)$t$),
  ($t$Jerry Tarkanian Statue Monument$t$, 36.1042056::double precision, -115.1441328::double precision, $t$This life-size bronze of Jerry Tarkanian, who coached UNLV's Runnin' Rebels from 1973 to 1992, was added outside the Thomas & Mack Center in 2013, eight years after the arena floor was named Jerry Tarkanian Court.$t$, $t$https://en.wikipedia.org/wiki/Jerry_Tarkanian$t$, $t$#449 hidden-pin row: osm_node4405730214, stored in 722_-2302, 722_-2303; containing tile 722_-2303 stores it (#542)$t$),
  ($t$Marjorie Barrick Museum of Art and Harry Reid Center$t$, 36.1069765::double precision, -115.1411316::double precision, $t$Founded in 1967 as a natural history museum of desert animals and Native American artifacts, the Marjorie Barrick Museum built a major pre-Columbian collection from 1979 and in 2011 joined UNLV's College of Fine Arts as the anchor of the Galleries at UNLV.$t$, $t$https://en.wikipedia.org/wiki/Marjorie_Barrick_Museum_of_Art$t$, $t$#449 hidden-pin row: osm_way129477688, stored in 722_-2302, 722_-2303; containing tile 722_-2303 stores it (#542)$t$),
  ($t$Sahara West Library and Fine Arts Museum$t$, 36.145051::double precision, -115.3052423::double precision, $t$Finished in 1997, this library shared its building with the Las Vegas Art Museum, which closed on February 28, 2009, citing falling donations; the library district now runs the former museum space as art galleries.$t$, $t$https://en.wikipedia.org/wiki/Las_Vegas_Art_Museum$t$, $t$#449 hidden-pin row: osm_way27523839, stored in 723_-2306; containing tile 723_-2306 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
